/**
 * 页面内录音（照 solofounder/Today 的做法收编）。
 *
 * 之前的坑：录完先用 Web Audio 解码转 WAV 再上传——iOS / 微信里 decodeAudioData 经常失败或 AudioContext 挂起，
 * 一失败就退回原始格式，等于白绕一圈。现在：浏览器录成什么就传什么（webm/opus 或 mp4），DashScope 都认。
 *
 * 几条硬规则：
 * - getUserMedia 只在安全上下文（HTTPS / localhost）下可用，http://192.168.x.x 连权限框都不弹——先判断、说人话
 * - 太短（<1200B）多半是误触，不值得发一趟请求；超过 60s 自动停
 * - 录音时给一条音量条，用户只需要知道"它确实在收"
 */
export const VOICE_FALLBACK_TIP = '当前浏览器不支持网页录音。请点输入框，用键盘上的麦克风（微信输入法 / 系统语音输入）说话转文字。';

export type VoiceSupport = 'recorder' | 'speech' | 'none';

export function detectVoiceSupport(): VoiceSupport {
  if (typeof window === 'undefined') return 'none';
  if (window.isSecureContext && !!navigator.mediaDevices?.getUserMedia && typeof MediaRecorder !== 'undefined') return 'recorder';
  const w = window as unknown as { SpeechRecognition?: unknown; webkitSpeechRecognition?: unknown };
  if (w.SpeechRecognition || w.webkitSpeechRecognition) return 'speech';
  return 'none';
}

/** 把拿麦克风失败的原因说清楚：被拒、没设备、不安全上下文，各不一样 */
export function explainMicError(e: unknown): string {
  if (typeof window !== 'undefined' && !window.isSecureContext) return '这个地址不是 HTTPS，浏览器不给麦克风权限。请用 https:// 的地址打开。';
  const name = (e as { name?: string })?.name || '';
  if (name === 'NotAllowedError' || name === 'SecurityError') return '麦克风权限被拒绝，请在浏览器设置里允许；或' + VOICE_FALLBACK_TIP.slice(12);
  if (name === 'NotFoundError') return '没有找到麦克风设备。';
  if (name === 'NotReadableError') return '麦克风被其他应用占用了，关掉再试。';
  return (e as Error)?.message || VOICE_FALLBACK_TIP;
}

export function pickMime(): string {
  const cands = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4', 'audio/ogg;codecs=opus'];
  return cands.find(m => { try { return MediaRecorder.isTypeSupported(m); } catch { return false; } }) || '';
}

export interface RecorderHandle {
  /** 停止并拿到音频；太短返回 null */
  stop(): Promise<Blob | null>;
  /** 丢弃 */
  cancel(): void;
  readonly mimeType: string;
}

export const MIN_BLOB_BYTES = 1200;
export const MAX_RECORD_MS = 60_000;

/**
 * 开始录音。onLevel 每帧回调 0～1 的音量，onMaxed 到 60s 自动停时回调（stop() 的 promise 会随之 resolve）。
 */
export async function startRecorder(opts: { onLevel?: (v: number) => void; onMaxed?: () => void; maxMs?: number } = {}): Promise<RecorderHandle> {
  if (typeof window !== 'undefined' && !window.isSecureContext) throw Object.assign(new Error('insecure'), { name: 'SecurityError' });
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  const mime = pickMime();
  const rec = mime ? new MediaRecorder(stream, { mimeType: mime }) : new MediaRecorder(stream);
  const chunks: Blob[] = [];
  rec.ondataavailable = e => { if (e.data && e.data.size > 0) chunks.push(e.data); };

  // 音量条：AudioContext 拿不到也不影响录音
  let ctx: AudioContext | null = null;
  let raf = 0;
  try {
    const AC = (window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext);
    if (AC && opts.onLevel) {
      ctx = new AC();
      const an = ctx.createAnalyser(); an.fftSize = 256;
      ctx.createMediaStreamSource(stream).connect(an);
      const buf = new Uint8Array(an.frequencyBinCount);
      const tick = () => {
        if (!ctx) return;
        an.getByteTimeDomainData(buf);
        let pk = 0; for (const v of buf) pk = Math.max(pk, Math.abs(v - 128));
        opts.onLevel?.(Math.min(1, pk / 58));
        raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    }
  } catch { /* ignore */ }

  const cleanup = () => {
    if (raf) cancelAnimationFrame(raf); raf = 0;
    stream.getTracks().forEach(t => t.stop());
    ctx?.close().catch(() => {}); ctx = null;
    opts.onLevel?.(0);
  };

  let stopped: ((b: Blob | null) => void) | null = null;
  const done = new Promise<Blob | null>(resolve => { stopped = resolve; });
  rec.onstop = () => {
    cleanup();
    clearTimeout(maxTimer);
    const blob = new Blob(chunks, { type: rec.mimeType || mime || 'audio/webm' });
    stopped?.(blob.size < MIN_BLOB_BYTES ? null : blob);
  };
  rec.start(200); // iOS Safari 不分片会给空 chunk
  const maxTimer = setTimeout(() => { if (rec.state === 'recording') { opts.onMaxed?.(); rec.stop(); } }, opts.maxMs ?? MAX_RECORD_MS);

  return {
    mimeType: rec.mimeType || mime,
    stop() {
      if (rec.state === 'recording') { try { rec.requestData(); } catch { /* ignore */ } rec.stop(); }
      else if (rec.state === 'inactive') stopped?.(null);
      return done;
    },
    cancel() {
      clearTimeout(maxTimer);
      rec.onstop = null; chunks.length = 0;
      if (rec.state !== 'inactive') { try { rec.stop(); } catch { /* ignore */ } }
      cleanup();
      stopped?.(null);
    },
  };
}

/** 上传转写：原生格式直传，服务端走 DashScope；返回文字（没听清返回空串） */
export async function transcribeBlob(blob: Blob): Promise<string> {
  const mime = (blob.type || 'audio/webm').split(';')[0];
  const ext = mime.includes('mp4') ? 'm4a' : mime.includes('ogg') ? 'ogg' : mime.includes('wav') ? 'wav' : 'webm';
  const fd = new FormData();
  fd.append('file', blob, `voice.${ext}`);
  fd.append('mimeType', blob.type || mime);
  const res = await fetch('/api/stt', { method: 'POST', body: fd });
  if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error || `HTTP ${res.status}`);
  const data = await res.json();
  return String(data.text || '').trim();
}
'use client';
/**
 * 语音输入：点一下开始录，再点一下停止并转写。
 *
 * 环境差异很大，按能力分三档，而不是假设 MediaRecorder 一定在：
 *   recorder — HTTPS + getUserMedia + MediaRecorder：页面内录音 → 原生格式直传 /api/stt（DashScope，2 秒出字）
 *   speech   — 只有浏览器自带的语音识别（webkitSpeechRecognition）：本地识别，不上传
 *   none     — 微信小程序 web-view、老版内嵌浏览器、非 HTTPS 地址：网页拿不到麦克风，提示用系统键盘的语音输入
 * 录音层在 @/lib/audio/recorder.ts（照 Today 项目收编）；主对话里的长按录音也走它。
 */
import { useCallback, useMemo, useRef, useState } from 'react';
import { startRecorder, transcribeBlob, detectVoiceSupport, explainMicError, VOICE_FALLBACK_TIP, type RecorderHandle, type VoiceSupport } from '@/lib/audio/recorder';

export { VOICE_FALLBACK_TIP, detectVoiceSupport };
export type { VoiceSupport };

type SpeechRecognitionCtor = new () => {
  lang: string; interimResults: boolean; maxAlternatives: number; continuous: boolean;
  onresult: ((ev: { results: ArrayLike<ArrayLike<{ transcript: string }>> }) => void) | null;
  onerror: ((ev: { error?: string }) => void) | null;
  onend: (() => void) | null;
  start(): void; stop(): void; abort(): void;
};

export function useVoiceInput(onText: (text: string) => void, onError?: (msg: string) => void) {
  const [recording, setRecording] = useState(false);
  const [recognizing, setRecognizing] = useState(false);
  const [level, setLevel] = useState(0);
  const recRef = useRef<RecorderHandle | null>(null);
  const speechRef = useRef<InstanceType<SpeechRecognitionCtor> | null>(null);
  // 只在客户端判断一次；SSR 时先当 none，避免 hydration 对不上
  const support = useMemo(() => detectVoiceSupport(), []);

  const finishRecorder = useCallback(async () => {
    const rec = recRef.current; recRef.current = null;
    if (!rec) return;
    setRecording(false); setRecognizing(true);
    try {
      const blob = await rec.stop();
      if (!blob) { onError?.('录音时间太短，再说一遍'); return; }
      const text = await transcribeBlob(blob);
      if (text) onText(text); else onError?.('没听清，再说一遍');
    } catch (e) {
      onError?.('语音识别失败：' + ((e as Error).message || '请重试'));
    } finally { setRecognizing(false); }
  }, [onText, onError]);

  const startRecorderMode = useCallback(async () => {
    try {
      recRef.current = await startRecorder({ onLevel: setLevel, onMaxed: () => { void finishRecorder(); } });
      setRecording(true);
    } catch (e) {
      onError?.(explainMicError(e));
    }
  }, [onError, finishRecorder]);

  const startSpeech = useCallback(() => {
    const w = window as unknown as { SpeechRecognition?: SpeechRecognitionCtor; webkitSpeechRecognition?: SpeechRecognitionCtor };
    const Ctor = w.SpeechRecognition || w.webkitSpeechRecognition;
    if (!Ctor) { onError?.(VOICE_FALLBACK_TIP); return; }
    const sr = new Ctor();
    sr.lang = 'zh-CN'; sr.interimResults = false; sr.maxAlternatives = 1; sr.continuous = false;
    sr.onresult = (ev) => {
      const text = Array.from({ length: ev.results.length }, (_, i) => ev.results[i][0]?.transcript || '').join('').trim();
      if (text) onText(text); else onError?.('没听清，再说一遍');
    };
    sr.onerror = (ev) => { onError?.(ev.error === 'not-allowed' ? '麦克风权限被拒绝' : VOICE_FALLBACK_TIP); };
    sr.onend = () => { setRecording(false); setRecognizing(false); speechRef.current = null; };
    speechRef.current = sr;
    setRecording(true);
    try { sr.start(); } catch { setRecording(false); onError?.(VOICE_FALLBACK_TIP); }
  }, [onText, onError]);

  const stopSpeech = useCallback(() => {
    setRecording(false); setRecognizing(true);
    try { speechRef.current?.stop(); } catch { setRecognizing(false); }
  }, []);

  const start = useCallback(async () => {
    if (support === 'recorder') return startRecorderMode();
    if (support === 'speech') return startSpeech();
    onError?.(VOICE_FALLBACK_TIP);
  }, [support, startRecorderMode, startSpeech, onError]);

  const stop = useCallback(() => {
    if (support === 'recorder') void finishRecorder(); else if (support === 'speech') stopSpeech();
  }, [support, finishRecorder, stopSpeech]);

  const cancel = useCallback(() => {
    recRef.current?.cancel(); recRef.current = null;
    try { speechRef.current?.abort(); } catch { /* ignore */ }
    setRecording(false); setRecognizing(false); setLevel(0);
  }, []);

  const toggle = useCallback(() => { if (recording) stop(); else void start(); }, [recording, start, stop]);
  return { support, recording, recognizing, level, start, stop, cancel, toggle };
}

